import java.io.*;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }

        Arrays.sort(a);

        long total = 0;

        // Fixa o maior lado em a[k] e conta pares (i, j) com i < j < k
        // tais que a[i] + a[j] > a[k], usando dois ponteiros: O(N^2)
        for (int k = n - 1; k >= 2; k--) {
            int i = 0, j = k - 1;
            while (i < j) {
                if (a[i] + a[j] > a[k]) {
                    // Todos os pares (i', j) com i <= i' < j também formam triângulo
                    total += j - i;
                    j--;
                } else {
                    i++;
                }
            }
        }

        System.out.println(total);
    }
}
